/* ===================== BÀI 10 · SFR và RAM gián tiếp ===================== */
/* Bài 10 · SFR và RAM gián tiếp (AMTS-EMB-001-M03-L02, MC51-010) — sinh bởi tools/author/mcu8051/l10.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const PR10=[{"label":"Ví dụ: Ghi và đọc qua con trỏ R0","code":"; Ví dụ 1: R0 chứa địa chỉ, @R0 là ô mà R0 trỏ tới\n; Chip: AT89S52, thạch anh 12 MHz.\n        ORG     0000H\n        MOV     R0,#40H                 ; R0 = địa chỉ 40H\n        MOV     @R0,#99H                ; ô 40H = 99H\n        INC     R0                      ; R0 = 41H: trỏ ô kế tiếp\n        MOV     @R0,#0AAH               ; ô 41H = AAH\n        MOV     A,@R0                   ; A = nội dung ô 41H\n        MOV     B,R0                    ; B = địa chỉ 41H\n        SJMP    $\n        END\n","note":"R0 giữ địa chỉ, @R0 là ô được trỏ tới. Sau INC R0, cùng lệnh MOV @R0,… ghi sang ô 41H. Cuối cùng A = AAH (nội dung ô 41H) còn B = 41H (chính giá trị của R0). Tổng 7 chu kỳ máy.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Ô E0H: thanh ghi A hay RAM cao?","code":"; Ví dụ 2: E0H trực tiếp là ACC, gián tiếp là RAM cao\n; Chip: AT89S52 (RAM trong 256 byte).\n        ORG     0000H\n        MOV     0E0H,#12H               ; trực tiếp E0H = ACC: A = 12H\n        MOV     R1,#0E0H                ; R1 trỏ E0H\n        MOV     @R1,#34H                ; gián tiếp: ô RAM cao E0H\n        MOV     B,@R1                   ; B = 34H (đọc RAM cao)\n        INC     @R1                     ; ô RAM cao E0H = 35H\n        SJMP    $\n        END\n","note":"Lệnh đầu ghi trực tiếp E0H nên A = 12H (xem phần Thanh ghi). Hai lệnh qua @R1 ghi và tăng ô RAM cao E0H (xem phần Bộ nhớ, hàng E0H) thành 35H, A vẫn 12H. Đoán trước: sau MOV B,@R1, B bằng bao nhiêu? (34H.)","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: MOV A,R0 khác MOV A,@R0","code":"; Ví dụ 3: giá trị của R0 và nội dung ô R0 trỏ tới\n; Chip: AT89S52.\n        ORG     0000H\n        MOV     30H,#77H                ; ô 30H = 77H\n        MOV     R0,#30H                 ; R0 = 30H (một địa chỉ)\n        MOV     A,R0                    ; A = 30H: lấy chính R0\n        MOV     B,@R0                   ; B = 77H: lấy ô 30H\n        SJMP    $\n        END\n","note":"Cùng R0 = 30H nhưng MOV A,R0 cho A = 30H (địa chỉ), còn MOV B,@R0 (mã 86 F0) cho B = 77H (nội dung ô 30H). Trình dịch chấp nhận cả hai cách viết.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Ngăn xếp trong RAM cao","code":"; Ví dụ 4: SP = 7FH, ngăn xếp nằm trong RAM cao\n; Chip: AT89S52. PUSH ghi gián tiếp qua SP.\n        ORG     0000H\n        MOV     SP,#7FH                 ; byte đầu tiên vào ô 80H\n        MOV     A,#5AH\n        MOV     B,#0A5H\n        PUSH    ACC                     ; SP = 80H, ô RAM cao 80H = 5AH\n        PUSH    B                       ; SP = 81H, ô RAM cao 81H = A5H\n        POP     30H                     ; ô 30H = A5H, SP = 80H\n        SJMP    $\n        END\n","note":"SP = 7FH nên PUSH ACC ghi ô RAM cao 80H, PUSH B ghi ô 81H (xem phần Ngăn xếp). SFR SP cũng ở địa chỉ 81H nhưng chỉ đổi giá trị 7FH → 80H → 81H → 80H, không bị ghi dữ liệu. POP 30H lấy byte trên cùng (A5H).","dev":{"led":true},"fosc":12000000},{"label":"Lỗi: Ngăn xếp ở 80H trên 8051 gốc","code":"; Ví dụ 5: ngăn xếp ở 80H khi chạy trên 8051 gốc\n; Chip: 8051 (RAM trong 128 byte: 00H-7FH).\n        ORG     0000H\n        MOV     SP,#7FH                 ; byte đầu tiên sẽ vào 80H\n        MOV     A,#5AH\n        PUSH    ACC                     ; 8051 không có ô 80H\n        POP     30H\n        SJMP    $\n        END\n","note":"Ví dụ này chạy ở cấu hình 8051 gốc (RAM trong 128 byte). PUSH ACC cần ghi ô 80H nhưng chip không có ô đó: trình mô phỏng dừng ở PC = 0005H và báo lỗi. Cùng chương trình trên AT89S52 chạy đúng (ví dụ 4).","dev":{"led":true},"fosc":12000000,"ram":128},{"label":"Bẫy: Con trỏ không tới được SFR","code":"; Ví dụ 6: định ghi 55H ra P0-P3 bằng con trỏ\n; Chip: AT89S52. LED P1 sáng khi chân = 0.\n        ORG     0000H\n        MOV     R0,#80H                 ; ý định: P0 ở 80H\n        MOV     R2,#4\nLAP:    MOV     @R0,#55H                ; gián tiếp: RAM cao, không SFR\n        MOV     A,R0\n        ADD     A,#10H                  ; 80H, 90H, A0H, B0H\n        MOV     R0,A\n        DJNZ    R2,LAP\n        SJMP    $\n        END\n","note":"Ý định ghi 55H ra bốn cổng, nhưng mọi lệnh MOV @R0 đều tới RAM cao: các ô 80H, 90H, A0H, B0H thành 55H, còn P0–P3 vẫn FFH và không LED nào ở P1 sáng. Chương trình chạy hết, không có thông báo lỗi.","dev":{"led":true},"fosc":12000000}];
